// Normalização e Cálculo de Custo por Milheiro (CPM) e Arbitragem
const items = $input.all();
const results = [];

for (const item of items) {
  const promo = item.json;
  const bonus = Number(promo.bonus_percentage || 0);
  const sourceProg = promo.source_program || 'Livelo';
  const targetProg = promo.target_program || 'Latam Pass';

  if (bonus < 30) continue; // Desprezar promoções fracas

  // CPM base de compra Livelo/Esfera R$ 35,00
  const cpmBase = 35.00;
  const effectiveCpm = cpmBase / (1 + bonus / 100);

  // Preço de venda de referência de mercado
  const marketCpmMap = {
    'Latam Pass': 24.50,
    'Smiles': 16.50,
    'Azul': 19.00,
    'Iberia': 75.00,
    'TAP': 32.00
  };
  const targetMarketCpm = marketCpmMap[targetProg] || 20.00;
  const spreadPercent = ((targetMarketCpm - effectiveCpm) / effectiveCpm) * 100;

  let score = 60;
  let priority = 'NORMAL';

  if (bonus >= 100 || spreadPercent >= 30) {
    score = 95;
    priority = 'CRITICAL_BUG';
  } else if (bonus >= 80 || spreadPercent >= 15) {
    score = 85;
    priority = 'HIGH';
  } else if (bonus >= 50) {
    score = 70;
    priority = 'NORMAL';
  }

  results.push({
    json: {
      category: 'miles_promo',
      title: `${bonus}% de Bônus: ${sourceProg} ➔ ${targetProg}`,
      description: `CPM Gerado: R$ ${effectiveCpm.toFixed(2)} vs Custo de Mercado R$ ${targetMarketCpm.toFixed(2)} | Spread: ${spreadPercent.toFixed(1)}%`,
      original_price: cpmBase * 10,
      opportunity_price: Number((effectiveCpm * 10).toFixed(2)),
      discount_percentage: Number(Math.max(0, spreadPercent).toFixed(2)),
      net_profit_estimate: spreadPercent > 0 ? Number((spreadPercent * 10).toFixed(2)) : 0,
      fipe_or_market_ref: Number(effectiveCpm.toFixed(2)),
      source_name: 'Radar de Milhas',
      source_url: promo.url || 'https://livelo.com.br',
      evaluation_score: score,
      priority: priority,
      raw_metadata: {
        bonus_percentage: bonus,
        effectiveCpm: Number(effectiveCpm.toFixed(2)),
        targetProg,
        sourceProg
      }
    }
  });
}

return results;
